<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AuthShell from'../../Components/AuthShell.vue';import UiButton from'../../Components/UiButton.vue';const form=useForm({email:''})</script>
<template><Head title="Forgot password"/><AuthShell eyebrow="Account recovery" title="Reset your password" description="Enter your LensPic account email. If it matches an account, we’ll send a secure reset link."><form class="space-y-5" @submit.prevent="form.post('/forgot-password')"><label class="lp-label">Email address<input v-model="form.email" type="email" autocomplete="email" class="field mt-2" required><span v-if="form.errors.email" class="lp-error">{{form.errors.email}}</span></label><UiButton type="submit" class="w-full" :loading="form.processing">Send reset link</UiButton><p class="text-center text-sm"><Link href="/login" class="font-semibold text-indigo hover:underline">Return to sign in</Link></p></form></AuthShell></template>
